// Memory mit 12 Karten (6 Paare), Cursor mit Richtungen, Feuer waehlt. Keine Uhr, nur Zuglimit.
const BILDER = ["🌞", "🌸", "⭐", "❤️", "🏠", "⚽"];
const SPALTEN = 4, ZEILEN = 3, ZELLE = 80, KARTE = 68, X0 = 26, Y0 = 150;
const ZUEGE = 24, WIEDERHOLEN = 12, ZEIGEN = 40;

export default {
  title: "Memory mit 12 bunten Karten",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const karten = [];
    for (const b of BILDER) {
      karten.push({ b, offen: false, paar: false });
      karten.push({ b, offen: false, paar: false });
    }
    for (let i = karten.length - 1; i > 0; i--) {
      const j = g.randInt(0, i);
      const t = karten[i]; karten[i] = karten[j]; karten[j] = t;
    }
    return { karten, cx: 0, cy: 0, halten: 0, wahl: [], zeigen: 0, zuege: 0, paare: 0, fertig: false };
  },

  update(s, input, g) {
    if (s.fertig) return;
    // zwei offene Karten ohne Paar kurz zeigen, dann wieder verdecken
    if (s.zeigen > 0) {
      s.zeigen -= 1;
      if (s.zeigen === 0) {
        for (const i of s.wahl) s.karten[i].offen = false;
        s.wahl = [];
      }
      return;
    }
    // Cursor: sofort beim Druecken, dann alle WIEDERHOLEN Frames solange gehalten
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    if (dx !== 0 || dy !== 0) {
      if (s.halten % WIEDERHOLEN === 0) {
        s.cx = g.clamp(s.cx + dx, 0, SPALTEN - 1);
        s.cy = g.clamp(s.cy + dy, 0, ZEILEN - 1);
      }
      s.halten += 1;
    } else s.halten = 0;

    if (!input.firePressed) return;
    const i = s.cy * SPALTEN + s.cx;
    const k = s.karten[i];
    if (k.offen || k.paar) return;
    k.offen = true;
    s.wahl.push(i);
    g.sound("pop");
    if (s.wahl.length < 2) return;

    s.zuege += 1;
    const a = s.karten[s.wahl[0]], b = s.karten[s.wahl[1]];
    if (a.b === b.b) {
      a.paar = true; b.paar = true;
      s.wahl = [];
      s.paare += 1;
      g.addScore(10);
      g.sound("coin");
      if (s.paare === BILDER.length) {
        s.fertig = true;
        g.addScore(Math.max(0, ZUEGE - s.zuege));
        g.win();
        return;
      }
    } else {
      g.addScore(1);
      s.zeigen = ZEIGEN;
    }
    if (s.zuege >= ZUEGE) g.gameOver();
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Züge: " + s.zuege + " / " + ZUEGE, g.W / 2, 90, { size: 20, align: "center" });
    for (let i = 0; i < s.karten.length; i++) {
      const k = s.karten[i];
      const x = X0 + (i % SPALTEN) * ZELLE, y = Y0 + Math.floor(i / SPALTEN) * ZELLE;
      if (k.paar) d.rect(x, y, KARTE, KARTE, "cream", { round: 10, line: true });
      else d.rect(x, y, KARTE, KARTE, k.offen ? "cream" : "yellow", { round: 10, shadow: true, line: true });
      if (k.offen || k.paar) d.emoji(k.b, x + KARTE / 2, y + KARTE / 2, 40);
    }
    if (!s.fertig) {
      const cx = X0 + s.cx * ZELLE - 6, cy = Y0 + s.cy * ZELLE - 6;
      d.rect(cx, cy, KARTE + 12, 4, "red");
      d.rect(cx, cy + KARTE + 8, KARTE + 12, 4, "red");
      d.rect(cx, cy, 4, KARTE + 12, "red");
      d.rect(cx + KARTE + 8, cy, 4, KARTE + 12, "red");
    } else {
      d.text("Glückwunsch, schön gemacht!", g.W / 2, g.H / 2, { size: 22, color: "ink", align: "center" });
    }
  }
};

// Wasserballon-Duell: zwei Boote am Teich, Zug um Zug am selben Geraet. Wer trifft, bekommt Punkte.
// Keine Gewalt, kein Blut: nur Wasserballons, Spritzer und Wellen.
// Der Holzsteg liegt links, damit Wuerfe zur Gegenlinie nicht zwangslaeufig an ihm zerplatzen.
const STEG = { x: 40, y: 316, w: 110, h: 14 };

export default {
  title: "Wasserballon-Duell auf dem Teich",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return { spieler: 1, zz: 180, halten: 0, flug: null, spritz: null, treffer: [0, 0], zuege: 0 };
  },

  update(s, input, g) {
    if (s.spritz) { s.spritz.t -= 1; if (s.spritz.t <= 0) s.spritz = null; }

    if (s.flug) {
      const f = s.flug;
      f.t += 1;
      const k = f.t / 30;
      f.x = f.x0 + (f.x1 - f.x0) * k;
      f.y = f.y0 + (f.y1 - f.y0) * k;
      // Steg: der Ballon platzt, kein Punkt
      if (f.y >= STEG.y && f.y <= STEG.y + STEG.h && f.x >= STEG.x && f.x <= STEG.x + STEG.w) {
        g.sound("pop");
        endeZug(s, g, false);
        return;
      }
      if (f.t >= 30) {
        endeZug(s, g, Math.abs(f.x1 - 180) <= 30);
      }
      return;
    }

    // Zielen: Zielmarke bewegen, mit fire werfen
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    if (dx !== 0) {
      if (s.halten % 12 === 0) s.zz = g.clamp(s.zz + 10 * dx, 20, 340);
      s.halten += 1;
    } else s.halten = 0;

    if (input.firePressed) {
      const sp = s.spieler;
      s.flug = { sp, x0: 180, y0: sp === 1 ? 150 : 490, x1: s.zz, y1: sp === 1 ? 500 : 140, t: 0, x: 180, y: sp === 1 ? 150 : 490 };
      s.halten = 0;
      g.sound("shoot");
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(10, 100, 340, 520, "cream", { round: 24, line: true });
    d.rect(STEG.x, STEG.y, STEG.w, STEG.h, "yellow", { round: 4, line: true });
    d.emoji("⛵", 180, 120, 40);
    d.emoji("🚤", 180, 520, 40);
    if (!s.flug) {
      const ziel = s.spieler === 1 ? 500 : 140;
      d.circle(s.zz, ziel, 7, "ink", { line: true });
    }
    if (s.flug) d.emoji("🎈", s.flug.x, s.flug.y, 26);
    if (s.spritz) d.emoji("💦", 180, s.spritz.y, 40);
    d.text(s.flug ? "Wurf läuft ..." : "Spieler " + s.spieler + " dran", 180, 84, { size: 20, align: "center" });
    d.text("Treffer: " + s.treffer[0] + " : " + s.treffer[1], 180, 610, { size: 18, align: "center" });
    d.text("Zug: " + s.zuege + " / 30", 180, 632, { size: 16, align: "center" });
  }
};

function endeZug(s, g, treffer) {
  const sp = s.flug.sp;
  s.flug = null;
  s.zuege += 1;
  if (treffer) {
    s.treffer[sp - 1] += 1;
    g.addScore(1);
    g.sound("hit");
    s.spritz = { y: sp === 1 ? 520 : 120, t: 40 };
    if (s.treffer[sp - 1] >= 5) { g.win(); return; }
  }
  s.spieler = 3 - sp;
  if (s.zuege >= 30) g.gameOver();
}

// Bunte Memory-Karten: 6 Paare gemalter Symbole, 12 verdeckte Karten. Feuer dreht um, Cursor mit Richtungen.
// Spielende: Zuglimit, Zeitlimit oder Ruhezeit nach dem Finale (Text bleibt sichtbar).
const BILDER = ["🌞", "🌸", "⛵", "🐸", "🍓", "🎈"];
const SPALTEN = 3, ZEILEN = 4, ZELLE = 76, KARTE = 68, X0 = 28, Y0 = 120;
const ZUEGE = 24, WIEDERHOLEN = 12, ZEIGEN = 120, DAUER = 2400, RUHE = 900;

export default {
  title: "Bunte Memory-Karten",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const s = { karten: [], cx: 0, cy: 0, halten: 0, wahl: [], zeigen: 0, zuege: 0, paare: 0, fertig: false, dauer: 0, ruhe: 0 };
    mische(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.fertig) {
      s.ruhe += 1;
      if (input.firePressed) { mische(s, g); return; }
      if (s.ruhe >= RUHE) g.gameOver();
      return;
    }
    s.dauer += 1;
    if (s.dauer >= DAUER) { g.gameOver(); return; }
    // zwei offene Karten ohne Paar: kurz zeigen, dann wieder verdecken
    if (s.zeigen > 0) {
      s.zeigen -= 1;
      if (s.zeigen === 0) {
        for (const i of s.wahl) s.karten[i].offen = false;
        s.wahl = [];
      }
      return;
    }
    // Cursor: sofort beim Druecken, dann alle WIEDERHOLEN Frames solange gehalten
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    if (dx !== 0 || dy !== 0) {
      if (s.halten % WIEDERHOLEN === 0) {
        s.cx = g.clamp(s.cx + dx, 0, SPALTEN - 1);
        s.cy = g.clamp(s.cy + dy, 0, ZEILEN - 1);
      }
      s.halten += 1;
    } else s.halten = 0;

    if (!input.firePressed) return;
    const i = s.cy * SPALTEN + s.cx;
    const k = s.karten[i];
    if (k.offen || k.weg) return;
    k.offen = true;
    s.wahl.push(i);
    g.sound("pop");
    if (s.wahl.length < 2) return;

    s.zuege += 1;
    const a = s.karten[s.wahl[0]], b = s.karten[s.wahl[1]];
    if (a.b === b.b) {
      a.weg = true; b.weg = true;
      s.wahl = [];
      s.paare += 1;
      g.addScore(10);
      g.sound("coin");
      if (s.paare === BILDER.length) { s.fertig = true; s.ruhe = 0; return; }
    } else {
      g.addScore(1);
      s.zeigen = ZEIGEN;
    }
    if (s.zuege >= ZUEGE) g.gameOver();
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Züge: " + s.zuege + " / " + ZUEGE, g.W / 2, 64, { size: 20, align: "center" });
    for (let i = 0; i < s.karten.length; i++) {
      const k = s.karten[i];
      const x = X0 + (i % SPALTEN) * ZELLE, y = Y0 + Math.floor(i / SPALTEN) * ZELLE;
      if (k.weg) { d.rect(x, y, KARTE, KARTE, "cream", { round: 10, line: true }); continue; }
      d.rect(x, y, KARTE, KARTE, k.offen ? "cream" : "yellow", { round: 10, shadow: true, line: true });
      if (k.offen) d.emoji(k.b, x + KARTE / 2, y + KARTE / 2, 40);
    }
    if (!s.fertig) {
      const cx = X0 + s.cx * ZELLE - 4, cy = Y0 + s.cy * ZELLE - 4;
      d.rect(cx, cy, ZELLE, 4, "red"); d.rect(cx, cy + ZELLE - 4, ZELLE, 4, "red");
      d.rect(cx, cy, 4, ZELLE, "red"); d.rect(cx + ZELLE - 4, cy, 4, ZELLE, "red");
    } else {
      d.text("Gut gemacht", g.W / 2, 90, { size: 28, align: "center" });
      d.text("Neue Runde mit Feuer", g.W / 2, 470, { size: 20, align: "center" });
    }
  }
};

function mische(s, g) {
  const karten = [];
  for (const b of BILDER) {
    karten.push({ b, offen: false, weg: false });
    karten.push({ b, offen: false, weg: false });
  }
  for (let i = karten.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = karten[i]; karten[i] = karten[j]; karten[j] = t;
  }
  s.karten = karten;
  s.cx = 0; s.cy = 0; s.halten = 0; s.wahl = []; s.zeigen = 0;
  s.zuege = 0; s.paare = 0; s.fertig = false; s.dauer = 0; s.ruhe = 0;
}

// Wasserballon-Duell: zwei Boote am Teich, Zug fuer Zug auf einem Geraet. Treffer aufs Segel zaehlt einen Punkt.
const YS = [500, 250], V = 10, G = 0.15, LIFE = 90, ZUGE = 30, TREFFER = 5;

function fresh() {
  return { x: [20, 300], y: [YS[0], YS[1]], wer: 0, zug: 0, treffer: [0, 0], ang: [60, 60], acool: 0, ballon: null, pop: null, kippen: [0, 0], ende: 0 };
}
function reset(s) {
  const f = fresh();
  for (const k of Object.keys(f)) s[k] = f[k];
}

export default {
  title: "Wasserballon-Duell auf dem Teich",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init() {
    return fresh();
  },

  update(s, input, g) {
    if (s.ende !== 0) { if (input.firePressed) reset(s); return; }
    for (let i = 0; i < 2; i++) if (s.kippen[i] > 0) s.kippen[i] -= 1;
    if (s.pop) { s.pop.t -= 1; if (s.pop.t <= 0) s.pop = null; }
    if (s.ballon) { flight(s, g); return; }

    const w = s.wer;
    if (input.left) s.x[w] = g.clamp(s.x[w] - 4, 0, g.W - 40);
    if (input.right) s.x[w] = g.clamp(s.x[w] + 4, 0, g.W - 40);
    if (input.up || input.down) {
      if (s.acool === 0) { s.ang[w] = g.clamp(s.ang[w] + (input.up ? 1 : -1), 20, 70); s.acool = 6; }
      else s.acool -= 1;
    } else s.acool = 0;

    if (input.firePressed) {
      const dir = w === 0 ? 1 : -1, a = s.ang[w];
      s.ballon = { x: s.x[w] + (dir > 0 ? 40 : 0), y: YS[w] + 8, vx: dir * V * g.cos(a), vy: -V * g.sin(a), n: 0 };
      s.zug += 1;
      g.sound("shoot");
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(10, 60, 340, 570, "yellow", { round: 16, line: true });
    d.text("Treffer " + s.treffer[0] + " : " + s.treffer[1] + "   Zug " + s.zug + " / " + ZUGE, g.W / 2, 74, { size: 18, align: "center", color: "ink" });
    d.text("Am Zug: Spieler " + (s.wer + 1), g.W / 2, 98, { size: 18, align: "center", color: "ink" });

    for (let i = 0; i < 2; i++) {
      const bx = s.x[i], by = YS[i];
      d.emoji("⛵", bx + 20, by + 15, 36);
      if (s.kippen[i] > 0) d.line(bx - 4, by + 24, bx + 44, by + (s.kippen[i] > 15 ? 4 : 28), "red", 3);
    }

    if (!s.ballon && s.ende === 0) {
      const w = s.wer, dir = w === 0 ? 1 : -1, a = s.ang[w];
      const tx = s.x[w] + (dir > 0 ? 40 : 0), ty = YS[w] + 8;
      d.line(tx, ty, tx + dir * 60 * g.cos(a), ty - 60 * g.sin(a), "red", 3);
      d.text(a + "°", tx + dir * 20, ty - 70, { size: 16, align: "center", color: "red" });
    }

    if (s.ballon) d.emoji("🎈", s.ballon.x, s.ballon.y, 22);
    if (s.pop) {
      d.circle(s.pop.x, s.pop.y, 4 + (20 - s.pop.t) * 1.2, "yellow", { line: true });
      d.emoji("💦", s.pop.x, s.pop.y, 28);
    }

    if (s.ende === 1 || s.ende === 2) {
      d.emoji("🎉", g.W / 2, 330, 80);
      d.text("Spieler " + s.ende + " gewinnt!", g.W / 2, 400, { size: 24, align: "center", color: "ink" });
      d.text("fire: neues Duell", g.W / 2, 440, { size: 16, align: "center", color: "ink" });
    } else if (s.ende === 3) {
      d.text("Zuglimit erreicht", g.W / 2, 400, { size: 24, align: "center", color: "ink" });
      d.text("fire: neues Duell", g.W / 2, 440, { size: 16, align: "center", color: "ink" });
    }
  }
};

function flight(s, g) {
  const b = s.ballon, w = s.wer, t = 1 - w;
  b.n += 1;
  b.vy += G;
  b.x += b.vx;
  b.y += b.vy;
  if (g.hit({ x: b.x, y: b.y, r: 6 }, { x: s.x[t] + 20, y: YS[t] + 4, r: 14 })) {
    s.treffer[w] += 1;
    g.addScore(1);
    g.sound("pop");
    s.pop = { x: b.x, y: b.y, t: 20 };
    s.kippen[t] = 30;
    s.ballon = null;
    s.wer = t;
    if (s.treffer[w] >= TREFFER) { s.ende = w + 1; g.win(); return; }
  } else if (b.n >= LIFE || b.y >= g.H - 30 || b.x < -20 || b.x > g.W + 20) {
    s.ballon = null;
    s.wer = t;
  } else return;
  if (s.zug >= ZUGE) { s.ende = 3; g.gameOver(); }
}
